mapper.select:
SELECT 1 FROM pf.execution_slot s WHERE s.id=1 AND s.task_id=#{lease.taskId,jdbcType=OTHER}
  AND s.owner_id=#{lease.ownerId,jdbcType=OTHER} AND s.fencing_token=#{lease.fence}
  AND s.lease_until>clock_timestamp() FOR UPDATE

SELECT 1 FROM pf.conversation_lease v WHERE v.space_id=#{lease.spaceId,jdbcType=OTHER}
  AND v.conversation_id=#{lease.conversationId,jdbcType=OTHER} AND v.task_id=#{lease.taskId,jdbcType=OTHER}
  AND v.attempt_id=#{lease.attemptId,jdbcType=OTHER} AND v.owner_id=#{lease.ownerId,jdbcType=OTHER}
  AND v.generation=#{lease.generation} AND v.fencing_token=#{lease.fence} AND v.lease_until>clock_timestamp() FOR UPDATE

SELECT 1 FROM pf.task t JOIN pf.membership m ON m.space_id=t.space_id AND m.user_id=t.creator_id
  WHERE t.id=#{lease.taskId,jdbcType=OTHER} AND t.space_id=#{lease.spaceId,jdbcType=OTHER}
    AND t.creator_id=#{lease.userId,jdbcType=OTHER} AND t.conversation_id=#{lease.conversationId,jdbcType=OTHER}
    AND t.status='RUNNING' AND NOT t.cancel_requested AND m.status='ACTIVE' FOR UPDATE OF t

SELECT 1 FROM pf.execution_dispatch d JOIN pf.attempt a ON a.task_id=d.task_id
  WHERE d.task_id=#{lease.taskId,jdbcType=OTHER} AND d.status='CLAIMED' AND d.lease_owner=#{lease.ownerId,jdbcType=OTHER}
    AND d.fencing_token=#{lease.fence} AND d.generation=#{lease.generation} AND d.lease_until>clock_timestamp()
    AND a.id=#{lease.attemptId,jdbcType=OTHER} AND a.space_id=#{lease.spaceId,jdbcType=OTHER}
    AND a.owner_id=#{lease.ownerId,jdbcType=OTHER} AND a.fencing_token=#{lease.fence} AND a.dispatch_generation=d.generation AND a.status='RUNNING'
    FOR UPDATE OF d,a

SELECT 1 FROM pf.task t JOIN pf.membership m ON m.space_id=t.space_id AND m.user_id=t.creator_id
  WHERE t.id=#{task,jdbcType=OTHER} AND t.creator_id=#{actor.userId,jdbcType=OTHER}
    AND t.space_id=#{actor.spaceId,jdbcType=OTHER} AND m.status='ACTIVE'
